      """
      Convert a single Sigma rule into the target data structure (usually query, see above).

      Args:
          rule: The Sigma rule to convert
          output_format: The output format to use for conversion
          callback: Optional callback function called for each condition conversion.
                   Receives (rule, output_format, index, cond, result) parameters and
                   returns a potentially modified result. The returned value replaces
                   the original conversion result. Return None to skip the result.
                   Called for every iteration, even when result is None.

      Returns:
          List of converted queries
      """
      try:
          # Initialize processing pipeline if not already done
          if (
              not hasattr(self, "last_processing_pipeline")
              or self.last_processing_pipeline is None
          ):
              self.init_processing_pipeline(output_format)

          error_state = "applying processing pipeline on"
          self.last_processing_pipeline.apply(rule)  # 1. Apply transformations

          # 2. Convert conditions
          error_state = "converting"
          states: list[ConversionState] = [
              ConversionState(processing_state=dict(self.last_processing_pipeline.state))
              for _ in rule.detection.parsed_condition
          ]
          queries = []
          for index, cond in enumerate(rule.detection.parsed_condition):
              state = states[index]
              result = self.convert_condition(cond.parsed, state)
              if result is not None:
                  result = self.finish_query(rule, result, state)
              if callback is not None:
                  result = callback(rule, output_format, index, cond, result)
              if result is not None:
                  queries.append(result)

          error_state = "finalizing query for"
          # 3. Postprocess generated query if not part of a correlation rule
          finalized_queries = (
              [
                  self.finalize_query(
                      rule,
                      query,
                      index,
                      states[index],
                      output_format or self.default_format,
                  )
                  for index, query in enumerate(queries)
              ]
              if self.finalize_correlation_subqueries or not rule._backreferences
              else queries
          )
          rule.set_conversion_result(finalized_queries)
          rule.set_conversion_states(states)
          if rule._output:
              return finalized_queries
          else:
              return []
      except SigmaError as e:
          if self.collect_errors:
              self.errors.append((rule, e))
              return []
          else:
              raise e
      except (
          Exception
      ) as e:  # enrich all other exceptions with Sigma-specific context information
          msg = f" (while {error_state} rule {str(rule.source)})"
          if len(e.args) > 1:
              e.args = (e.args[0] + msg,) + e.args[1:]
          else:
              e.args = (e.args[0] + msg,)
          raise

  def _format_template(
      self: Self,
      template: str,
      **kwargs: str | int | float | list[str] | SigmaCorrelationRule | None,
  ) -> str:
      """
      Ensure all template's variables are properly populated before generating the output.

      :param template: Templated string to format.
      :type cond: str
      :param kwargs: List of parameters to populate the template.
      :type kwargs: str | int | float | list[str] | SigmaCorrelationRule | None
      :return: Templated string
      :rtype: str
      """
      variables: list[tuple[str, str | int | float | list[str] | SigmaCorrelationRule | None]] = [
          (parsed_template[1], kwargs.get(parsed_template[1]))
          for parsed_template in string.Formatter().parse(template)
          if parsed_template[1]
      ]

      for variable_name, variable_value in variables:
          if variable_name == "referenced_rules" and variable_value is None:
              raise SigmaBackendError(
                  "Backend doesn't define referenced rule expression but uses it in correlation query template"
              )

      return template.format(**kwargs)

  def decide_convert_condition_as_in_expression(
      self, cond: ConditionOR | ConditionAND, state: ConversionState
  ) -> bool:
      """
      Decide if an OR or AND expression should be converted as "field in (value list)" or as plain expression.

      :param cond: Condition that is converted for which the decision has to be made.
      :type cond: ConditionOR | ConditionAND
      :param state: Current conversion state.
      :type state: ConversionState
      :return: True if in-expression should be generated, else False
      :rtype: bool
      """
      # Check if conversion of condition type is enabled
      if (
          not self.convert_or_as_in
          and isinstance(cond, ConditionOR)
          or not self.convert_and_as_in
          and isinstance(cond, ConditionAND)
      ):
          return False

      # Check if more than one argument is present
      # if len(cond.args <= 1):
      #    return False

      # All arguments of the given condition must reference a field
      if not all((isinstance(arg, ConditionFieldEqualsValueExpression) for arg in cond.args)):
          return False
      # After the check it can be assumed that all arguments are of type ConditionFieldEqualsValueExpression
      args = cast(list[ConditionFieldEqualsValueExpression], cond.args)

      # Build a set of all fields appearing in condition arguments
      fields = {arg.field for arg in args}
      # All arguments must reference the same field
      if len(fields) != 1:
          return False

      # All argument values must be strings or numbers
      if not all([isinstance(arg.value, (SigmaString, SigmaNumber)) for arg in args]):
          return False

      # Check for plain strings if wildcards are not allowed for string expressions.
      if not self.in_expressions_allow_wildcards and any(
          [arg.value.contains_special() for arg in args if isinstance(arg.value, SigmaString)]
      ):
          return False

      # All checks passed, expression can be converted to in-expression
      return True

