    backend: Backend,
    rules: (
        SigmaCollection
        | SigmaRule
        | SigmaCorrelationRule
        | Mapping[str, Any]
        | str
        | Sequence[SigmaRule | SigmaCorrelationRule | Mapping[str, Any]]
